-- ============================================================
-- DATE HELPER
-- ============================================================
local function calcDaysSinceUpdate()
    local updateTs = os.time({
        year  = LAST_UPDATE.year,
        month = LAST_UPDATE.month,
        day   = LAST_UPDATE.day,
        hour  = 0, min = 0, sec = 0
    })
    return math.floor((os.time() - updateTs) / 86400)
end

local function daysAgoStr(n)
    if     n == 0  then return "Today"
    elseif n == 1  then return "Yesterday"
    elseif n <  7  then return n .. " days ago"
    elseif n <  14 then return "1 week ago"
    elseif n <  21 then return "2 weeks ago"
    elseif n <  28 then return "3 weeks ago"
    elseif n <  60 then return "1 month ago"
    else                return math.floor(n / 30) .. " months ago"
    end
end

