        { user = "RobloxSnack",      text = "this is actually kinda addictive lol"           },
        { user = "LilChaosDev",      text = "everything just feels right here"               },
        { user = "xXRandomProXx",    text = "ok yeah this is valid af"                       },
    }

    for _, t in ipairs(testimonials) do
        local row = Instance.new("Frame", revScroll)
        row.Size             = UDim2.new(1, 0, 0, 26)
        row.BackgroundColor3 = INPUT
        corner(row, 5)
        local uLbl = Instance.new("TextLabel", row)
        uLbl.Size               = UDim2.new(0, 120, 1, 0)
        uLbl.Position           = UDim2.new(0, 6, 0, 0)
        uLbl.BackgroundTransparency = 1
        uLbl.Text               = t.user
        uLbl.TextColor3         = ACCENT
        uLbl.Font               = Enum.Font.GothamBold
        uLbl.TextSize           = 10
        uLbl.TextXAlignment     = Enum.TextXAlignment.Left
        local tLbl = Instance.new("TextLabel", row)
        tLbl.Size               = UDim2.new(1, -130, 1, 0)
        tLbl.Position           = UDim2.new(0, 126, 0, 0)
        tLbl.BackgroundTransparency = 1
        tLbl.Text               = '"' .. t.text .. '"'
        tLbl.TextColor3         = DIM
        tLbl.Font               = Enum.Font.Gotham
        tLbl.TextSize           = 10
        tLbl.TextXAlignment     = Enum.TextXAlignment.Left
