    -- BUY BUTTON
    local buyBtn = Instance.new("TextButton", shopCard)
    buyBtn.Size             = UDim2.new(1, -24, 0, 44)
    buyBtn.Position         = UDim2.new(0, 12, 0, revY + 130)
    buyBtn.BackgroundColor3 = ACCENT
    buyBtn.Text             = ""
    buyBtn.AutoButtonColor  = false
    corner(buyBtn, 10)
    mkStroke(buyBtn, ACCENT2, 1, 0.3)

    local bTxt = lbl(buyBtn, "🛒  Get Lifetime Now!",
        UDim2.new(0, 0, 0, 0), UDim2.new(1, 0, 1, 0),
        TEXT, 14, true, Enum.TextXAlignment.Center)

    buyBtn.MouseButton1Click:Connect(function()
        pcall(function() setclipboard(SHOP_LINK) end)
        bTxt.Text = "✅ Link Copied!"
        task.delay(2.5, function()
            if bTxt and bTxt.Parent then
                bTxt.Text = "🛒  Get Lifetime Now!"
            end
        end)
    end)

    local function closeShop()
        shopOpen = false
        tw(shopCard, 0.3, {Position = UDim2.new(0.5, 420, 0.5, 0)}):Play()
        task.wait(0.35)
        if sg and sg.Parent then sg:Destroy() end
        shopGuiRef = nil
    end
    closeBtn.MouseButton1Click:Connect(closeShop)

    shopCard.Size = UDim2.new(0, 370, 0, revY + 200)
end

